import{_ as t,o,c as a,a3 as r}from"./chunks/framework.Ki30n65y.js";const s="/depgate/screenshots/exceptions.png",i="/depgate/screenshots/exception-add.png",n="/depgate/screenshots/waivers-review.png",p="/depgate/screenshots/waiver-approve.png",m=JSON.parse('{"title":"Exceptions and waivers","description":"","frontmatter":{},"headers":[],"relativePath":"admin/exceptions.md","filePath":"admin/exceptions.md"}'),l={name:"admin/exceptions.md"};function d(c,e,h,g,v,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="exceptions-and-waivers" tabindex="-1">Exceptions and waivers <a class="header-anchor" href="#exceptions-and-waivers" aria-label="Permalink to &quot;Exceptions and waivers&quot;">​</a></h1><p>An <strong>exception</strong> lets a package through despite your policies, until an expiry date. Use exceptions for a short, deliberate gap: an urgent fix while you verify a package, a pinned version while a team upgrades, or a pilot of a new library.</p><p>Exceptions always expire. When one expires, the package is blocked again; nothing needs to be cleaned up.</p><p>There are two ways an exception is created:</p><ul><li>A <strong>Security</strong> user adds it directly.</li><li>A developer submits a <strong>waiver request</strong>, and a Security user approves it.</li></ul><h2 id="the-exceptions-page" tabindex="-1">The Exceptions page <a class="header-anchor" href="#the-exceptions-page" aria-label="Permalink to &quot;The Exceptions page&quot;">​</a></h2><p>In the sidebar, choose <strong>Exceptions</strong>. The <strong>Exceptions</strong> tab lists every exception with its package and versions, status (<strong>Active</strong> or <strong>Expired</strong>), repositories, expiry and approver. Filter by package name, ecosystem, status and <strong>Applies to</strong>.</p><p><img src="'+s+'" alt="The Exceptions page"></p><p>Choose the eye icon on a row to see the full details, including the reason. <strong>Revoke</strong> is in that view.</p><h2 id="add-an-exception" tabindex="-1">Add an exception <a class="header-anchor" href="#add-an-exception" aria-label="Permalink to &quot;Add an exception&quot;">​</a></h2><ol><li><p>Choose <strong>Add exception</strong>.</p></li><li><p>Fill in the form:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Ecosystem</strong></td><td>The package&#39;s ecosystem.</td></tr><tr><td><strong>Package name</strong></td><td>The exact name.</td></tr><tr><td><strong>Versions</strong> (optional)</td><td>Single versions or ranges. Leave empty to cover every version. Prefer exact versions.</td></tr><tr><td><strong>Applies to</strong></td><td><strong>All repositories</strong>, or only selected ones.</td></tr><tr><td><strong>Expires</strong></td><td>When the exception ends. Keep it as short as the need.</td></tr><tr><td><strong>Reason</strong></td><td>Why it is safe and needed. Auditors read it.</td></tr></tbody></table></li><li><p>Choose <strong>Create</strong>.</p></li></ol><p><img src="'+i+'" alt="Adding an exception"></p><p>From <a href="/depgate/developers/package-check">Package check</a>, <strong>Add exception</strong> on a blocked version opens this form with the package and version filled in.</p><div class="warning custom-block"><p class="custom-block-title">What an exception covers</p><p>An exception added here covers <strong>every</strong> policy and the malware list for the versions it names. It does not lift <a href="./namespace-protection">namespace protection</a>; for that, use an exception scoped to the namespace policy.</p></div><h2 id="review-waiver-requests" tabindex="-1">Review waiver requests <a class="header-anchor" href="#review-waiver-requests" aria-label="Permalink to &quot;Review waiver requests&quot;">​</a></h2><p>Developers cannot create exceptions. They submit <a href="/depgate/developers/waiver-requests">waiver requests</a>, which appear on the <strong>Waiver requests</strong> tab of the Exceptions page. The badge on the tab shows how many are pending.</p><p><img src="'+n+'" alt="Pending waiver requests"></p><ol><li>Choose <strong>Review</strong> on a pending request.</li><li>Read the package, versions, repositories, requester, requested expiry and reason.</li><li>To approve, set the expiry the exception will use (you can keep the requested date or choose another) and, if needed, narrow or widen the repositories. Optionally add a note. Choose <strong>Approve</strong>.</li><li>To reject, choose <strong>Reject</strong> and explain why in the note. The developer sees it.</li></ol><p><img src="'+p+'" alt="Reviewing a waiver request"></p><p>Approval creates the exception at once. Until then the package stays blocked. A rejected request creates nothing; the developer can edit it and send it back for review.</p><h2 id="policy-scoped-approvals" tabindex="-1">Policy-scoped approvals <a class="header-anchor" href="#policy-scoped-approvals" aria-label="Permalink to &quot;Policy-scoped approvals&quot;">​</a></h2><p>An exception normally covers every policy. An <strong>approval</strong> created from the <a href="./monitoring#approve-packages">Monitoring</a> page is scoped to <strong>one</strong> policy: it stops only that policy from matching, and every other policy still decides. For example, approving a package&#39;s license does not let through a version with a blocked vulnerability.</p><ul><li>Approvals are listed on the Exceptions page when <strong>Applies to</strong> is set to <strong>One policy</strong>, and under <strong>Approved packages</strong> in the policy itself.</li><li>Deleting a policy revokes its approvals.</li><li>The malware list ignores approvals.</li></ul><h2 id="repository-scope" tabindex="-1">Repository scope <a class="header-anchor" href="#repository-scope" aria-label="Permalink to &quot;Repository scope&quot;">​</a></h2><p>Exceptions and waiver requests can be limited to repositories, just like <a href="./policies#limit-a-policy-to-some-repositories">policies</a>:</p><ul><li>An exception on a <strong>remote</strong> lets the package through wherever that remote serves it.</li><li>An exception on a <strong>virtual</strong> repository lets it through that URL only.</li><li>Deleting a repository deletes exceptions limited only to it, and rejects pending waivers limited only to it.</li></ul><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Creating, approving, rejecting and revoking exceptions and waivers are all recorded in the <a href="./audit-log">Audit Log</a>, with the person who did it.</p>',28)])])}const y=t(l,[["render",d]]);export{m as __pageData,y as default};
